// The public-corpus table: one row of numbers per reviewed public repo, plus column totals that re-add from
// the rows. See docs/DESIGN.md §"Public corpus".

/** One repo's numbers in the corpus table. costUsd is null when no session in the repo could be priced. */
export interface CorpusRow {
  repo: string;
  sessions: number;
  setups: number;
  costUsd: number | null;
  /** Setup id the review flagged, or null. */
  suspect: string | null;
  /** Candidate replays gated for this repo. */
  replayed: number;
  /** Setup id promoted for this repo, or null when nothing was promoted. */
  promoted: string | null;
}

export interface CorpusTotals {
  repos: number;
  sessions: number;
  costUsd: number | null;
  replayed: number;
  promotions: number;
}

export interface CorpusTable {
  rows: CorpusRow[];
  totals: CorpusTotals;
}

/**
 * Rows sorted by sessions descending, then repo ascending. Totals are the column sums of the returned rows and
 * are accumulated in that order, so re-adding the rows reproduces them exactly. The cost total sums the priced
 * rows only and stays null when every row is unpriced — a corpus with nothing priced has no cost, not $0.
 * `promotions` counts rows that name a promoted setup. The input is left untouched.
 */
export function buildCorpusTable<R extends CorpusRow>(reviews: readonly R[]): { rows: R[]; totals: CorpusTotals } {
  const rows = [...reviews].sort((a, b) => b.sessions - a.sessions || a.repo.localeCompare(b.repo));

  let sessions = 0;
  let costUsd: number | null = null;
  let replayed = 0;
  let promotions = 0;
  for (const r of rows) {
    sessions += r.sessions;
    replayed += r.replayed;
    if (r.promoted !== null) promotions++;
    if (r.costUsd !== null) costUsd = (costUsd ?? 0) + r.costUsd;
  }

  return { rows, totals: { repos: rows.length, sessions, costUsd, replayed, promotions } };
}

import { describe, expect, test } from "bun:test";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { buildCorpusTable, type CorpusRow } from "../src/review/corpus-table.ts";

const ROOT = join(import.meta.dir, "..");
const REPORTS = join(ROOT, "reports");

const num = (xs: unknown[]): number[] => xs.filter((x): x is number => typeof x === "number");

/**
 * One row per reviewed repo, built from the review.json files under reports/ (the generated corpus). The
 * public reviews record no gate run, so their replayed/promoted stay empty; the roster repo's row takes both
 * from reports/self/review-1/decisions.json when it is there. "_sample" is a hand-written shape sample, not a
 * reviewed repo, so it is left out.
 */
function rowsFromReports(): CorpusRow[] {
  const rows: CorpusRow[] = [];
  for (const entry of readdirSync(REPORTS, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    if (!entry.isDirectory() || entry.name === "_sample" || entry.name === "corpus") continue;
    const path = join(REPORTS, entry.name, "review.json");
    if (!existsSync(path)) continue;
    const review = JSON.parse(readFileSync(path, "utf8")) as {
      repo: string;
      suspect: string | null;
      setups: { sessions: number; spend_usd: number | null }[];
    };
    const priced = num((review.setups ?? []).map((s) => s.spend_usd));
    rows.push({
      repo: review.repo,
      sessions: (review.setups ?? []).reduce((n, s) => n + s.sessions, 0),
      setups: (review.setups ?? []).length,
      costUsd: priced.length === 0 ? null : priced.reduce((a, b) => a + b, 0),
      suspect: review.suspect ?? null,
      replayed: 0,
      promoted: null,
    });
    if (entry.name === "rajkaria__roster") {
      const decisionsPath = join(REPORTS, "self", "review-1", "decisions.json");
      if (existsSync(decisionsPath)) {
        const decisions = JSON.parse(readFileSync(decisionsPath, "utf8")) as { promoted: string | null; decisions: unknown[] };
        rows[rows.length - 1]!.replayed = decisions.decisions.length;
        rows[rows.length - 1]!.promoted = decisions.promoted;
      }
    }
  }
  return rows;
}

const real = rowsFromReports();

/** The rows as a caller would re-add them: the returned order, which is what totals must match. */
const reAdd = (rows: CorpusRow[]) => ({
  repos: rows.length,
  sessions: rows.reduce((n, r) => n + r.sessions, 0),
  costUsd: rows.some((r) => r.costUsd !== null) ? rows.reduce((n, r) => n + (r.costUsd ?? 0), 0) : null,
  replayed: rows.reduce((n, r) => n + r.replayed, 0),
  promotions: rows.filter((r) => r.promoted !== null).length,
});

describe.skipIf(real.length === 0)("buildCorpusTable on the reports/ reviews", () => {
  const table = buildCorpusTable(real);

  test("keeps every repo, one row each", () => {
    expect(table.rows.length).toBe(real.length);
    expect(new Set(table.rows.map((r) => r.repo)).size).toBe(real.length);
    expect([...table.rows].sort((a, b) => a.repo.localeCompare(b.repo))).toEqual([...real].sort((a, b) => a.repo.localeCompare(b.repo)));
  });

  test("sorts by sessions descending, then repo", () => {
    for (let i = 1; i < table.rows.length; i++) {
      const prev = table.rows[i - 1]!;
      const cur = table.rows[i]!;
      expect(prev.sessions >= cur.sessions).toBe(true);
      if (prev.sessions === cur.sessions) expect(prev.repo.localeCompare(cur.repo)).toBeLessThan(0);
    }
  });

  test("totals equal the sums of the rows", () => {
    expect(table.totals).toEqual(reAdd(table.rows));
  });

  test("a row's sessions is the sum of its setups' sessions", () => {
    const byRepo = new Map(real.map((r) => [r.repo, r]));
    for (const row of table.rows) expect(row.sessions).toBe(byRepo.get(row.repo)!.sessions);
  });
});

describe("buildCorpusTable totals", () => {
  const base = real.length > 0 ? real : [{
    repo: "owner/name",
    sessions: 3,
    setups: 1,
    costUsd: 1.25,
    suspect: null,
    replayed: 0,
    promoted: null,
  }];

  test("an empty corpus has zero rows and no cost", () => {
    expect(buildCorpusTable([])).toEqual({
      rows: [],
      totals: { repos: 0, sessions: 0, costUsd: null, replayed: 0, promotions: 0 },
    });
  });

  test("cost is null when every row is unpriced", () => {
    const unpriced = base.map((r) => ({ ...r, costUsd: null }));
    const { totals } = buildCorpusTable(unpriced);
    expect(totals.costUsd).toBeNull();
    expect(totals).toEqual(reAdd(buildCorpusTable(unpriced).rows));
  });

  test("cost sums the priced rows and skips the unpriced ones", () => {
    const rows = base.map((r, i) => ({ ...r, repo: `owner/${i}`, sessions: i, costUsd: i === 0 ? null : r.costUsd }));
    const priced = num(rows.map((r) => r.costUsd));
    const { totals } = buildCorpusTable(rows);
    expect(totals.costUsd).toBeCloseTo(priced.reduce((a, b) => a + b, 0), 10);
    expect(totals).toEqual(reAdd(buildCorpusTable(rows).rows));
  });

  test("promotions counts rows with a promoted setup, replayed sums every row", () => {
    const rows: CorpusRow[] = [
      { repo: "owner/a", sessions: 2, setups: 1, costUsd: 1, suspect: "X", replayed: 2, promoted: "E" },
      { repo: "owner/b", sessions: 1, setups: 2, costUsd: null, suspect: null, replayed: 1, promoted: null },
      { repo: "owner/c", sessions: 1, setups: 1, costUsd: 3, suspect: null, replayed: 0, promoted: "F" },
    ];
    const { totals } = buildCorpusTable(rows);
    expect(totals).toEqual({ repos: 3, sessions: 4, costUsd: 4, replayed: 3, promotions: 2 });
    expect(totals).toEqual(reAdd(buildCorpusTable(rows).rows));
  });

  test("ties on sessions fall back to repo ascending", () => {
    const tied = base.slice(0, 2).map((r) => ({ ...r, sessions: 7, repo: r.repo }));
    if (tied.length < 2) return;
    const { rows } = buildCorpusTable(tied);
    expect(rows.map((r) => r.repo)).toEqual([...tied.map((r) => r.repo)].sort((a, b) => a.localeCompare(b)));
  });

  test("does not mutate or alias the input array", () => {
    const input = real.length > 1 ? [...real] : [
      { repo: "owner/small", sessions: 1, setups: 1, costUsd: null, suspect: null, replayed: 0, promoted: null },
      { repo: "owner/big", sessions: 9, setups: 1, costUsd: null, suspect: null, replayed: 0, promoted: null },
    ];
    const before = [...input];
    const { rows } = buildCorpusTable(input);
    expect(input).toEqual(before);
    expect(rows).not.toBe(input);
  });
});

